import{_ as o,C as n,c as r,o as i,a3 as t,G as s}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Stages","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/setup/stages.md","filePath":"master/supply-chain/maintenance/setup/stages.md","lastUpdated":1793074831000}'),l={name:"master/supply-chain/maintenance/setup/stages.md"};function d(h,e,g,c,p,u){const a=n("ImagePopup");return i(),r("div",null,[e[0]||(e[0]=t('<h1 id="stages" tabindex="-1">Stages <a class="header-anchor" href="#stages" aria-label="Permalink to &quot;Stages&quot;">​</a></h1><p>A stage is one step in the life of a maintenance request. The stages show as a bar on top of every request, so you see at once where the work stands. A flag called <strong>Done</strong> tells Aureus which stages mean the job is finished.</p><blockquote><p><strong>In simple words:</strong> Stages are the steps of a job. The Done flag marks the last steps.</p></blockquote><p>Other modules, such as projects and recruitment, also use stages. The idea is the same everywhere. See <a href="./../../../getting-started/stages.html">Stages in Getting started</a>.</p><p>Open <code>Maintenance → Configurations → Stages</code>.</p><h2 id="the-seeded-stages" tabindex="-1">The seeded stages <a class="header-anchor" href="#the-seeded-stages" aria-label="Permalink to &quot;The seeded stages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Stage</th><th>Done</th><th>What it means</th></tr></thead><tbody><tr><td><strong>New Request</strong></td><td>No</td><td>A problem is reported. Work has not started</td></tr><tr><td><strong>In Progress</strong></td><td>No</td><td>A technician is working on it</td></tr><tr><td><strong>Repaired</strong></td><td>Yes</td><td>The job is finished</td></tr><tr><td><strong>Scrap</strong></td><td>Yes</td><td>The equipment cannot be fixed and is you stop using it</td></tr></tbody></table>',7)),s(a,{src:"/images1/maintenance/set_stages_list.png",alt:"Maintenance Stages list with New Request, In Progress, Repaired and Scrap, with green Done ticks on Repaired and Scrap"}),e[1]||(e[1]=t('<p>The list has a <strong>Name</strong> column and a <strong>Done</strong> column. A green tick means Yes. A red cross means No.</p><h2 id="what-the-done-flag-does" tabindex="-1">What the Done flag does <a class="header-anchor" href="#what-the-done-flag-does" aria-label="Permalink to &quot;What the Done flag does&quot;">​</a></h2><p>A request counts as closed when its stage has <strong>Done</strong> switched on. Then:</p><ul><li>It leaves the <strong>To Do</strong> tab and appears on the <strong>Done</strong> tab of the request list.</li><li>It shows in green on the calendar. Open jobs show in blue.</li><li>If it is a recurring preventive request, Aureus creates the next copy when you save it in this stage.</li></ul><h2 id="create-a-stage" tabindex="-1">Create a stage <a class="header-anchor" href="#create-a-stage" aria-label="Permalink to &quot;Create a stage&quot;">​</a></h2><ol><li>Open <code>Maintenance → Configurations → Stages</code>.</li><li>Click <strong>New Stage</strong>. A window opens.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Name:</em></strong> Required. For example <code>Waiting for Parts</code>.</li><li><strong><em>Done:</em></strong> Switch on only if the job is finished at this stage. It starts off.</li></ul>',7)),s(a,{src:"/images1/maintenance/set_stage_form.png",alt:"Create Maintenance Stage window with the name Waiting for Parts and the Done toggle off"}),e[2]||(e[2]=t('<ol start="4"><li>Click <strong>Create</strong>.</li></ol><h2 id="change-the-order" tabindex="-1">Change the order <a class="header-anchor" href="#change-the-order" aria-label="Permalink to &quot;Change the order&quot;">​</a></h2><p>The order of the list is the order of the bar on each request. To change it:</p><ol><li>Click the reorder button at the left of the toolbar.</li><li>Drag a row up or down.</li><li>Click the button again to finish.</li></ol><p>New requests always start in the first stage. Keep the done stages last.</p><h2 id="edit-group-and-delete" tabindex="-1">Edit, group and delete <a class="header-anchor" href="#edit-group-and-delete" aria-label="Permalink to &quot;Edit, group and delete&quot;">​</a></h2><p>Click <strong>Edit</strong> to rename a stage or change its Done flag. Use <strong>Group by</strong> to group the list by <strong>Done</strong>. Click <strong>Delete</strong> to remove a stage.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Do not delete a stage while requests use it. Move those requests to another stage first.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Keep the list short, three to five stages. A long bar is hard to read.</p></div><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./maintenance-teams.html">Maintenance teams</a></li><li><a href="./../requests/process-request.html">Process a request</a></li><li><a href="./../requests/preventive-maintenance.html">Preventive maintenance</a></li><li><a href="./../../../getting-started/stages.html">Stages in Getting started</a></li></ul>',11))])}const _=o(l,[["render",d]]);export{f as __pageData,_ as default};
